<template>
  <section class="flex flex-col gap-6">
    <PageTitle title="Staffing Resources">
      <ReferralFormDialog @success="refetch">
        <template #default>
          <Button>Invite</Button>
        </template>
      </ReferralFormDialog>

      <NuxtLink :to="{ name: 'staffing-resources-import' }">
        <Button>Import CSV</Button>
      </NuxtLink>
    </PageTitle>
    <StaffingContactsListFilters :params="params" />
    <Alert v-if="selection.count.value > 0" class="sticky top-0 z-10">
      <Mail class="mt-2.5" />
      <AlertTitle class="flex flex-wrap items-center justify-between min-h-9 gap-2">
        {{ selection.count.value === 1 ? '1 contact' : `${selection.count.value} contacts` }} selected
        <div class="flex items-center gap-2">
          <Button size="sm" @click="isSendBatchDialogOpen = true"> Send Batch Email </Button>
          <ResetCountersDialog
            v-if="isAdmin"
            mode="batch"
            :contacts="selection.selectedItems.value"
            @reset="selection.clear()"
          >
            <Button size="sm" variant="outline" :prepend-icon="RotateCcwIcon">Reset Counters</Button>
          </ResetCountersDialog>
          <Button variant="outline" size="sm" @click="selection.clear()"> Clear selection </Button>
        </div>
      </AlertTitle>
    </Alert>

    <!-- Outside the count-gated Alert on purpose: a partial send clears the selection, unmounting the
         Alert and its skip-reason list mid-render. -->
    <RecruitmentSendBatchDialog
      v-if="defaultChannelStrategy"
      v-model="isSendBatchDialogOpen"
      mode="general"
      :selected-contacts="selection.selectedItems.value"
      :default-channel-strategy="defaultChannelStrategy"
      default-strategy-source="general_settings"
      @sent="selection.clear()"
    />
    <Card>
      <AppLoader v-if="isLoading" subject="staffing resources" variant="inline" />
      <AppError v-else-if="error" :error="error" title="Failed to load staffing resources" variant="table" />
      <ResponsiveTable v-else rounded>
        <ResponsiveTableHeader>
          <ResponsiveTableHead class="w-10">
            <Checkbox
              :model-value="selection.pageSelectAllState(data?.items ?? [])"
              @update:model-value="() => selection.togglePage(data?.items ?? [])"
            />
          </ResponsiveTableHead>
          <ResponsiveTableHead class="text-nowrap"> Email </ResponsiveTableHead>
          <ResponsiveTableHead> Name </ResponsiveTableHead>
          <ResponsiveTableHead> Phone </ResponsiveTableHead>
          <ResponsiveTableHead class="text-nowrap"> Total Projects </ResponsiveTableHead>
          <ResponsiveTableHead> Readiness </ResponsiveTableHead>
          <ResponsiveTableHead class="text-nowrap"> Recruitment </ResponsiveTableHead>
          <ResponsiveTableHead> Source </ResponsiveTableHead>
          <ResponsiveTableHead class="text-nowrap"> General Sent </ResponsiveTableHead>
          <ResponsiveTableHead class="text-nowrap"> Project Sent </ResponsiveTableHead>
        </ResponsiveTableHeader>
        <ResponsiveTableBody>
          <ResponsiveTableEmpty
            v-if="!data || data.items.length === 0"
            :colspan="10"
            :cols="4"
            :cols-sm="4"
            class="text-center"
          >
            <AppGuidedEmpty v-if="showGuided && guidedContent" v-bind="guidedContent" variant="table" />
            <AppEmpty v-else variant="table" subject="staffing resources" />
          </ResponsiveTableEmpty>
          <ResponsiveTableRow
            v-for="contact in data?.items"
            :key="contact.email"
            :to="{ name: 'staffing-resources-email', params: { email: contact.email } }"
          >
            <ResponsiveTableCell :cols="1" :cols-sm="1" @click.stop.prevent>
              <Checkbox
                :model-value="selection.isSelected(contact.email)"
                @update:model-value="() => selection.toggle(contact)"
              />
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Email">
              {{ contact.email }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Name">
              {{ formatContactName(contact.first_name, contact.last_name) }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Phone" class="text-nowrap">
              {{ contact.phone_number || '—' }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Total Projects">
              {{ contact.total_projects }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Readiness">
              <Badge v-if="contact.readiness_stage" :variant="getReadinessStage(contact.readiness_stage).variant">
                {{ getReadinessStage(contact.readiness_stage).label }}
              </Badge>
              <span v-else class="text-muted-foreground">—</span>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Recruitment">
              <div class="flex flex-wrap items-center gap-1">
                <Badge :variant="getRecruitmentStatus(contact.recruitment_status).variant">
                  {{ getRecruitmentStatus(contact.recruitment_status).label }}
                </Badge>
                <Badge v-if="exhaustionLabel(contact)" variant="destructive">
                  {{ exhaustionLabel(contact) }}
                </Badge>
              </div>
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="2" :cols-sm="2" label="Source" class="text-nowrap">
              {{ getStaffingContactSource(contact.source).label }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="1" :cols-sm="1" label="General Sent">
              {{ contact.general_message_count }}
            </ResponsiveTableCell>
            <ResponsiveTableCell :cols="1" :cols-sm="1" label="Project Sent">
              {{ contact.project_message_count }}
            </ResponsiveTableCell>
          </ResponsiveTableRow>
        </ResponsiveTableBody>
        <ResponsiveTableFooter
          v-if="!error && !isLoading && data && data.total_count > 0"
          :colspan="10"
          :cols="4"
          :cols-sm="4"
        >
          <AppPagination :page="params.page" :total="data.total_count" :size="params.size" label="contacts" />
        </ResponsiveTableFooter>
      </ResponsiveTable>
    </Card>
  </section>
</template>

<script setup lang="ts">
import {
  getAllSystemSettings,
  getStaffingContactList,
  type GetAllSystemSettingsResponse,
  type GetStaffingContactListData,
  type GetStaffingContactListResponse,
  type RecruitmentStatus,
  type StaffingContactListItem,
  type StaffingContactSortBy,
  type StaffingContactSource,
  type SortType,
} from '~/client';
import { staffingContactsGuidedEmpty } from '~/constants/guidedEmpty/staffingContacts';
import { getRecruitmentStatus } from '~/constants/staffing-contacts/recruitmentStatusConfig';
import { getStaffingContactSource } from '~/constants/staffing-contacts/staffingContactSourceConfig';
import { getReadinessStage } from '~/constants/recruitment/readinessStageConfig';
import { Checkbox } from '~/components/ui/checkbox';
import { Alert, AlertTitle } from '~/components/ui/alert';
import { Mail, RotateCcwIcon } from 'lucide-vue-next';
import { shouldClearSelectionOnNav } from '~/utils/recruitment/selectionNavReset';
import { exhaustionLabel } from '~/utils/recruitment/exhaustionLabel';

definePageMeta({
  roles: ['admin', 'manager'],
  backLabel: 'staffing contacts',
});

useHead({
  title: 'Staffing Resources',
});

const route = useRoute('staffing-resources');
const { isAdmin } = useUserRole();

const params = computed((): NonNullable<GetStaffingContactListData['query']> => {
  const queryParams = {
    ...parsePagination(route.query, { size: 50 }),
    sort_type: (route.query.sort_type as SortType) || 'asc',
    sort_by: (route.query.sort_by as StaffingContactSortBy) || 'general_priority',
    search_query: (route.query.search_query as string) || undefined,
    projects: processArrayQueryParameterFromUrl<string>(route.query.projects),
    states: processArrayQueryParameterFromUrl<string>(route.query.states),
    cities: processArrayQueryParameterFromUrl<string>(route.query.cities),
    remotes: processArrayQueryParameterFromUrl<string>(route.query.remotes),
    military_statuses: processArrayQueryParameterFromUrl<string>(route.query.military_statuses),
    additional_languages: processArrayQueryParameterFromUrl<string>(route.query.additional_languages),
    relationships: processArrayQueryParameterFromUrl<string>(route.query.relationships),
    grades: processArrayQueryParameterFromUrl<string>(route.query.grades),
    leaderships: processArrayQueryParameterFromUrl<string>(route.query.leaderships),
    levels: processArrayQueryParameterFromUrl<string>(route.query.levels),
    total_projects_min: route.query.total_projects_min ? Number(route.query.total_projects_min) : undefined,
    total_projects_max: route.query.total_projects_max ? Number(route.query.total_projects_max) : undefined,
    is_contacted: parseBooleanQuery(route.query.is_contacted as string),
    top_canvasser: parseBooleanQuery(route.query.top_canvasser as string),
    top_petitioner: parseBooleanQuery(route.query.top_petitioner as string),
    background_check_complete: parseBooleanQuery(route.query.background_check_complete as string),
    is_registered: parseBooleanQuery(route.query.is_registered as string),
    recruitment_status: processArrayQueryParameterFromUrl<RecruitmentStatus>(route.query.recruitment_status),
    source: processArrayQueryParameterFromUrl<StaffingContactSource>(route.query.source),
  };

  return Object.fromEntries(Object.entries(queryParams).filter(([_, value]) => value !== undefined)) as NonNullable<
    GetStaffingContactListData['query']
  >;
});

const { data, error, isLoading, refetch } = useQuery({
  key: () => ['staffing-contacts.list', params.value],
  query: (): Promise<GetStaffingContactListResponse> =>
    getStaffingContactList({ composable: '$fetch', query: ref(params.value) }),
  staleTime: 0,
});

const isEmpty = computed(() => !data.value || data.value.items.length === 0);
const { guidedContent, showGuided } = useGuidedEmpty(staffingContactsGuidedEmpty, isEmpty);

const selection = useCrossPageSelection<StaffingContactListItem>((c) => c.email);
const isSendBatchDialogOpen = ref(false);

const { data: settingsData } = useQuery({
  key: () => ['system-settings'],
  query: (): Promise<GetAllSystemSettingsResponse> => getAllSystemSettings({ composable: '$fetch' }),
});

const defaultChannelStrategy = computed(() => settingsData.value?.general_recruitment.channel_strategy);

const FILTER_KEYS = [
  'sort_by',
  'sort_type',
  'projects',
  'recruitment_status',
  'source',
  'total_projects_min',
  'total_projects_max',
  'is_contacted',
  'top_canvasser',
  'top_petitioner',
  'background_check_complete',
  'is_registered',
] as const;
// Router hook, not a watch: cross-page selection must survive page/size nav, so reset only when the
// FILTER_KEYS projection actually changes value.
onBeforeRouteUpdate((to, from) => {
  const next = FILTER_KEYS.map((k) => to.query[k]);
  const prev = FILTER_KEYS.map((k) => from.query[k]);
  if (shouldClearSelectionOnNav(next, prev)) selection.clear();
});
</script>
