<template>
  <Dialog v-model:open="isVisible">
    <DialogTrigger as-child>
      <slot />
    </DialogTrigger>
    <DialogContent class="gap-6">
      <DialogHeader>
        <DialogTitle> Invite a canvasser </DialogTitle>
        <DialogDescription> Provide contact information and let Grace handle the communication. </DialogDescription>
      </DialogHeader>
      <ReferralForm @success="onSuccess" />
    </DialogContent>
  </Dialog>
</template>

<script setup lang="ts">
const isVisible = ref<boolean>(false);

interface Emit {
  (e: 'success'): void;
}

const emits = defineEmits<Emit>();

function onSuccess() {
  isVisible.value = false;
  emits('success');
}
</script>

